'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=t=>t?new Date(t*1000).toLocaleString('en-ZA',{dateStyle:'medium',timeStyle:'short'}):'Not connected';
let state={devices:[],claims:[],audit:[]}, account=null, selectedClaim=null, selectedDevice=null, enrollment=null,qrUrl=null,controlRequest=null;
async function api(path,options={}){const r=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers}});if(!r.ok){let message;try{const b=await r.json();message=typeof b.detail==='string'?b.detail:'Check all required fields.';}catch{message='Request failed. Please retry.';}if(r.status===401&&path!='/auth/login')showLogin();throw Object.assign(new Error(message),{status:r.status});}return r.json();}
function notice(text){const panel=$('#notice');panel.replaceChildren(document.createTextNode(text));const close=document.createElement('button');close.type='button';close.className='notice-close';close.textContent='×';close.setAttribute('aria-label','Dismiss message');close.onclick=()=>{panel.hidden=true;};panel.append(close);panel.classList.remove('is-error');panel.hidden=false;}
function error(e){notice(e.message);$('#notice').classList.add('is-error');const open=document.querySelector('dialog[open]');if(open){let p=open.querySelector('.dialog-error');if(!p){p=document.createElement('p');p.className='dialog-error';p.setAttribute('role','alert');open.append(p);}p.textContent=e.message;}}
async function busy(form,fn){const buttons=form.querySelectorAll('button[type=submit]');buttons.forEach(b=>b.disabled=true);try{await fn();}catch(e){error(e);}finally{buttons.forEach(b=>b.disabled=false);}}
function showLogin(){$('#login').hidden=false;$('#workspace').hidden=true;account=null;document.querySelectorAll('dialog[open]').forEach(d=>d.close());}
function money(amount){const value=Number(amount);return new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR',minimumFractionDigits:2}).format(Number.isFinite(value)?value:0);}
function initials(name){return String(name||'Customer').trim().split(/\s+/).slice(0,2).map(part=>part[0]||'').join('').toUpperCase();}
const uiIcons={check:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>',search:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>',message:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round" aria-hidden="true"><path d="M21 4H3v14h5l4 4 4-4h5V4Z"/><path d="M7 9h10M7 13h6"/></svg>'};
let activeView='overview',paymentFilter='all';
function emptyState(title,description,action='',icon='check'){return '<div class="empty">'+(uiIcons[icon]||uiIcons.check)+'<strong>'+esc(title)+'</strong><p>'+esc(description)+'</p>'+action+'</div>';}
function showView(view){if(!['overview','devices','payments','messages','support','audit'].includes(view))return;activeView=view;try{localStorage.setItem('loop-admin-view',view);}catch{}for(const name of ['overview','devices','payments','messages','support','audit'])$('#'+name+'-view').hidden=name!==view;document.querySelectorAll('nav [data-view]').forEach(button=>{const current=button.dataset.view===view;button.classList.toggle('active',current);if(current)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});const copy={overview:['Overview','Your accounts and the next steps that matter.','Overview'],devices:['Customers','A clear register of customer accounts and phone reports.','Customers'],payments:['Payments','Check the bank transaction and record your decision.','Payments'],messages:['Messages','Send useful updates and follow their delivery.','Messages'],support:['Support','Give customer questions a clear next step.','Support'],audit:['Activity log','Account decisions and changes, in one record.','Activity log']}[view];$('#page-title').textContent=copy[0];$('#page-description').textContent=copy[1];$('#page-section').textContent=copy[2];$('.sidebar').classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Open navigation');}
function badge(status){const labels={pending:'Awaiting review',approved:'Approved',rejected:'Rejected',unrestricted:'Unrestricted',restricted:'Restricted',not_enrolled:'Setup pending',needs_online_check:'Online check needed',restricted_banking_unavailable:'Banking unavailable',policy_error:'Policy error',unsupported:'Management unsupported',released:'Released',open:'Open',resolved:'Resolved'};return `<span class="badge ${esc(status)}">${esc(labels[status]||String(status||'Unknown').replaceAll('_',' '))}</span>`;}
function paymentCard(p){return `<article class="payment-card"><span class="customer-avatar" aria-hidden="true">${esc(initials(p.name))}</span><div class="payment-info"><h3>${esc(p.name)}</h3><p>${esc(p.reference)} · ${esc(date(p.submitted))}</p><p class="submitted-ref">Claim reference: ${esc(p.bank_reference||'Not supplied')}</p></div><div class="payment-action"><div class="amount">${esc(money(p.amount))}</div>${p.state==='pending'&&account.role!=='viewer'?`<button data-review="${esc(p.id)}" aria-label="Review payment from ${esc(p.name)}">Review claim <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14m-5-5 5 5-5 5"/></svg></button>`:badge(p.state)}</div>${p.state!=='pending'?`<div class="claim-decision">${badge(p.state)}${p.reviewed?' · Reviewed '+esc(date(p.reviewed)):''}${p.reason?' · '+esc(p.reason):''}</div>`:''}</article>`;}
function renderPayments(){const claims=state.claims.filter(claim=>(paymentFilter==='all'||claim.state===paymentFilter)&&matchesPaymentQuery(claim,$('#payment-search')?.value||''));const pendingTotal=paymentSnapshot().pending;$('#payment-results').textContent=paymentFilter==='pending'&&pendingTotal>claims.length?claims.length+' of '+pendingTotal+' pending claims available':claims.length+' '+(claims.length===1?'claim':'claims')+(paymentFilter==='all'?' available':' '+paymentFilter);$('#payments-list').innerHTML=claims.map(paymentCard).join('')||emptyState(paymentFilter==='pending'&&pendingTotal?'Pending claims need retrieval.':paymentFilter==='all'?'No payment claims yet.':'No '+(paymentFilter==='pending'?'pending':paymentFilter)+' claims.',paymentFilter==='pending'&&pendingTotal?'Pending claims are outside the currently available history. Refresh records or contact support to retrieve them.':paymentFilter==='all'?'Claims appear here when enrolled customers report an EFT payment.':'Choose another filter to view the available payment history.');document.querySelectorAll('[data-payment-filter]').forEach(button=>{const selected=button.dataset.paymentFilter===paymentFilter;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected));if(button.closest('#payments-view .segmented-control')){button.dataset.baseLabel??=button.textContent.trim();button.textContent=button.dataset.baseLabel+' ('+state.claims.filter(c=>button.dataset.paymentFilter==='all'||c.state===button.dataset.paymentFilter).length+')';}});}
function paymentSnapshot(){const approved=state.claims.filter(p=>p.state==='approved'),summary=state.payment_summary;const allTime=!!summary&&summary.approved_total!=null&&summary.approved_count!=null&&Number.isFinite(Number(summary.approved_total))&&Number.isFinite(Number(summary.approved_count));return{allTime,total:allTime?Number(summary.approved_total):approved.reduce((sum,p)=>sum+(Number.isFinite(Number(p.amount))?Number(p.amount):0),0),count:allTime?Number(summary.approved_count):approved.length,pending:summary&&summary.pending_count!=null&&Number.isFinite(Number(summary.pending_count))?Number(summary.pending_count):state.claims.filter(p=>p.state==='pending').length};}
function render(){renderUpdateFleet();const pending=state.claims.filter(p=>p.state==='pending'),approved=state.claims.filter(p=>p.state==='approved'),payments=paymentSnapshot();$('#account-role').textContent=account.role==='owner'?'Owner workspace':account.role==='viewer'?'View-only workspace':'Reviewer workspace';$('#pending').textContent=payments.pending;$('#pending-count').textContent=payments.pending;$('#pending-count').hidden=!payments.pending;$('#total').textContent=state.devices.filter(d=>d.enforcement_status!=='not_enrolled').length;$('#overdue').textContent=state.devices.filter(d=>!d.released&&d.due<state.server_time).length;$('#delivery').textContent=state.devices.filter(d=>Number(d.acknowledged_revision)<Number(d.revision)).length;$('#approved-amount').textContent=money(payments.total);$('#approved-count').textContent=payments.count;$('#summary-scope').textContent=payments.allTime?'All time':'Available history';$('#recorded-count').textContent=state.claims.length;$('#receipt-caption').textContent=payments.allTime?'All approved payments across customer accounts.':approved.length?'Approved payments within the claim history available here.':'No approved payments in the available claim history yet.';$('#payment-scope').textContent=payments.allTime?'Approved receipts only. A finance payoff balance is not supplied.':'All pending claims and up to 200 latest records. Approved receipts only; no payoff balance.';$('#inbox').innerHTML=[...pending].sort((a,b)=>a.submitted-b.submitted).slice(0,3).map(paymentCard).join('')||(payments.pending?emptyState('More claims need review.','There are '+payments.pending+' pending claims outside the currently available history. Refresh records or contact support to retrieve them.','<button data-refresh class="secondary">Refresh records</button><a href="mailto:basanisilinda@gmail.com">Contact support</a>'):emptyState('No payments waiting for review','New EFT claims appear here when customers report a payment.'));renderPayments();renderTransactions();renderDevices();renderOverviewRegister();renderHealthAlerts();renderFleetHealth();renderMessages();renderSupport();$('#audit-list').innerHTML=state.audit.map(a=>`<article class="activity"><time>${esc(date(a.at))}</time><div><strong>${esc(a.action.replaceAll('_',' '))}</strong><p>${esc(a.detail)}</p></div></article>`).join('')||emptyState('A fresh start.','Account decisions and workspace changes will appear here as they happen.');}
function renderMessages(){$('#messages-list').innerHTML=(state.messages||[]).map(m=>{const recipients=Math.max(0,Number(m.recipients)||0),delivered=Math.max(0,Number(m.delivered)||0),read=Math.max(0,Number(m.read_count)||0);return `<article class="message-card panel"><div class="message-card-heading"><div><h3>${esc(m.title)}</h3><time>${esc(date(m.created))}</time></div><span class="small-icon">${uiIcons.message}</span></div><p class="message-body">${esc(m.body)}</p><div class="message-receipts"><div class="receipt-counts"><span><strong>${delivered} / ${recipients}</strong> delivered</span><span><strong>${read}</strong> read</span></div><progress value="${Math.min(delivered,recipients)}" max="${Math.max(1,recipients)}" aria-label="Message delivered to ${delivered} of ${recipients} recipients"></progress><small>${Math.max(0,recipients-delivered)} awaiting delivery. Phones receive queued messages when they reconnect.</small></div></article>`;}).join('')||emptyState('Start a useful conversation.','Send payment guidance or an account update. Delivery and read receipts appear as phones report back.',account.role!=='viewer'?'<button data-compose>Write a message</button>':'','message');}
function renderSupport(){const tickets=state.support||[];const open=tickets.filter(ticket=>ticket.state==='open').length;$('#support-count').textContent=open+' open';$('#support-list').innerHTML=[...tickets].sort((a,b)=>(a.state==='open'?0:1)-(b.state==='open'?0:1)||b.created-a.created).map(t=>`<article class="support-card panel"><div class="support-card-heading"><div><h3>${esc(t.name)}</h3><p class="support-reference">${esc(t.reference)}</p><time>${esc(date(t.created))}</time></div>${badge(t.state)}</div><p class="message-body">${esc(t.message)}</p>${t.state==='open'&&account.role!=='viewer'?`<div class="support-card-actions"><button data-reply="${esc(t.device_id)}">Reply to customer</button><button data-resolve="${esc(t.id)}" class="secondary">Mark resolved</button></div>`:''}</article>`).join('')||emptyState('No support requests yet.','Messages sent from enrolled customer phones appear here.','', 'message');}
function renderDevices(){const query=$('#search').value.trim().toLowerCase(),filter=$('#customer-filter').value;const devices=state.devices.filter(d=>[d.name,d.reference,d.phone].some(value=>String(value||'').toLowerCase().includes(query))).filter(d=>filter==='all'||(filter==='pending'&&Number(d.acknowledged_revision)<Number(d.revision))||(filter==='connected'&&d.enforcement_status!=='not_enrolled'&&!d.released&&d.last_seen&&state.server_time-d.last_seen<=900)||(filter==='overdue'&&!d.released&&d.due<state.server_time)||(filter==='setup'&&d.enforcement_status==='not_enrolled')||(filter==='released'&&d.released)||(filter==='update'&&updateNeeded(d)));devices.sort((a,b)=>compareCustomerRecords(a,b,$('#customer-sort')?.value||'name'));refreshCustomerChips();$('#customer-results').textContent=devices.length+' of '+state.devices.length+' customers';$('#devices-table').innerHTML=devices.map(d=>{const pending=Number(d.acknowledged_revision)<Number(d.revision),recent=d.last_seen&&state.server_time-d.last_seen<=900;return `<tr><td data-label="Customer"><div class="customer-cell"><span class="customer-avatar" aria-hidden="true">${esc(initials(d.name))}</span><div><strong>${esc(d.name)}</strong><small>${esc(d.phone)}</small></div></div></td><td data-label="Account"><div class="record-reference">${esc(d.reference)} <button type="button" class="copy-reference secondary" data-copy-reference="${esc(d.reference)}" aria-label="Copy customer reference">Copy</button></div><div class="account-date">Paid to ${esc(date(d.due))}</div>${d.approved_total!=null&&d.approved_count!=null?`<small class="customer-paid">${esc(money(d.approved_total))} approved · ${esc(d.approved_count)} payments</small>${d.payment_summary?`<small>${esc(d.payment_summary.progress_percent)}% of ${esc(money(d.payment_summary.contract_total))} · ${esc(money(d.payment_summary.remaining_balance))} remaining</small>`:''}`:''}${d.released?'<small>Fully paid · release recorded</small>':''}</td><td data-label="Phone">${badge(d.enforcement_status)}<small>${esc(d.model||'Waiting for phone setup')}</small><small>${esc(updateDescription(d))}</small></td><td data-label="Latest report"><span class="delivery-label ${pending?'':'confirmed'}">${pending?'Confirmation pending':'Revision acknowledged'}</span><span class="contact-label ${recent?'recent':''}">${recent?'Recent contact':'Last contact'} · ${esc(date(d.last_seen))}</span></td><td data-label="Actions">${account.role==='owner'?`<div class="record-actions"><button data-device="${esc(d.id)}" class="secondary" aria-label="Manage ${esc(d.name)}">Manage</button>${d.enforcement_status==='not_enrolled'?`<button data-qr="${esc(d.id)}" aria-label="Open enrollment QR for ${esc(d.name)}">Setup QR</button>`:''}</div>`:'<small>Read only</small>'}</td></tr>`;}).join('')||'<tr><td colspan="5" class="table-empty">'+emptyState(state.devices.length?'No customers match.':'Ready for your first customer.',state.devices.length?'Try a different name, phone number or status filter.':'Enroll a customer with their name and phone number to create their connection.',state.devices.length?'<button data-clear-filters class="secondary">Clear search &amp; filters</button>':account.role==='owner'?'<button data-enroll>Enroll customer</button>':'','search')+'</td></tr>';}
function renderOverviewRegister(){const query=$('#overview-search').value.trim().toLowerCase(),devices=state.devices.filter(d=>[d.name,d.phone,d.reference].some(value=>String(value||'').toLowerCase().includes(query))),visible=devices.slice(0,5);$('#overview-customer-results').textContent=query?devices.length+' matching '+(devices.length===1?'customer':'customers'):devices.length>5?'Showing 5 of '+devices.length+' customers':devices.length+' '+(devices.length===1?'customer':'customers');$('#overview-customers').innerHTML=visible.map(d=>`<tr><td><div class="customer-cell"><span class="customer-avatar" aria-hidden="true">${esc(initials(d.name))}</span><div><strong>${esc(d.name)}</strong><small>${esc(d.reference)} · ${esc(d.phone)}</small></div></div></td><td><span class="account-date">${esc(date(d.due))}</span>${d.approved_total!=null&&d.approved_count!=null?`<small>${esc(money(d.approved_total))} approved · ${esc(d.approved_count)} payments</small>${d.payment_summary?`<small>${esc(d.payment_summary.progress_percent)}% of ${esc(money(d.payment_summary.contract_total))} · ${esc(money(d.payment_summary.remaining_balance))} remaining</small>`:''}`:''}</td><td>${badge(d.enforcement_status)}<small>${esc(d.model||'Waiting for phone setup')}</small><small>${esc(updateDescription(d))}</small></td><td>${account.role==='owner'?`<button class="secondary" data-device="${esc(d.id)}" aria-label="Manage ${esc(d.name)}">Manage</button>`:'<small>Read only</small>'}</td></tr>`).join('')||'<tr><td colspan="4" class="table-empty">'+emptyState(state.devices.length?'No customers match your search':'Your customer register starts here',state.devices.length?'Search by a different name, mobile number or reference.':'Add a customer’s name and mobile number, then connect their phone.',!state.devices.length&&account.role==='owner'?'<button data-enroll>New customer</button>':'','search')+'</td></tr>';}
function setEnrollmentStep(step){const details=$('#enrollment-step-details'),phone=$('#enrollment-step-phone');details.classList.toggle('current',step===1);details.classList.toggle('complete',step===2);phone.classList.toggle('current',step===2);for(const [item,current]of [[details,step===1],[phone,step===2]]){if(current)item.setAttribute('aria-current','step');else item.removeAttribute('aria-current');}$('#enrollment-title').textContent=step===1?'New customer':'Phone setup';}
function deviceAlerts(device,serverTime){
 const alerts=[];const add=(code,severity,title,detail)=>alerts.push({code,severity,title,detail});
 if(!Number.isFinite(serverTime)||serverTime<=0)return alerts;
 if(device.enforcement_status==='not_enrolled')return alerts;
 const seen=Number(device.last_seen)||0;
 if(!seen||serverTime-seen>900)add('contact',1,'No recent contact',seen?'No device report for over 15 minutes. The phone may be offline or suspended.':'No device contact has been recorded.');
 if(device.released){if(device.enforcement_status!=='released')add('release',1,'Release awaiting confirmation','The paid-off release was requested, but the device has not reported completion.');return alerts;}
 let policy;try{policy=typeof device.policy==='string'?JSON.parse(device.policy):device.policy;if(!policy||typeof policy!=='object')throw Error();}catch{add('policy',0,'Policy needs attention','The saved policy could not be read. Open the device to check its configuration.');return alerts;}
 if(device.enforcement_status==='policy_error')add('enforcement',0,'Device reported a policy error','The last report did not confirm successful enforcement. Check the phone’s management status.');
 if(policy.enforcement_enabled&&device.enforcement_status==='unsupported')add('ownership',0,'Management unsupported','The device reports that device-owner management is unavailable. Ordinary installation is insufficient.');
 if(device.enforcement_status==='restricted_banking_unavailable')add('banking',1,'Banking app unavailable','The device reports a restriction but no approved bank app. The customer can use EFT from another device or contact support.');
 if(device.enforcement_status==='needs_online_check')add('clock',1,'Account verification needed','The phone needs an online check to verify its deadline after restart.');
 const current=Number(device.acknowledged_revision)>=Number(device.revision);
 if(!current)add('delivery',2,'Change awaiting acknowledgement','The latest account or policy revision has not been acknowledged. A request is not confirmation.');
 const due=Number(device.due),grace=Number(policy.grace_hours??24),restrictionDue=Math.max(due+grace*3600,Number(policy.grace_until)||0);
 if(policy.enforcement_enabled&&policy.manual_lock&&current&&seen>=serverTime-900&&device.enforcement_status==='unrestricted')add('manual_lock',0,'Requested lock not confirmed','A recent report still says unrestricted after the latest lock command. Check the phone and install the latest managed client.');
 if(policy.enforcement_enabled&&current&&seen>=serverTime-900&&seen>=restrictionDue&&Number.isFinite(due)&&Number.isFinite(grace)&&serverTime>=restrictionDue&&device.enforcement_status==='unrestricted')add('overdue',0,'Overdue restriction not confirmed','A recent report still says unrestricted after the grace period. Check the actual phone before assuming it is locked.');
 return alerts;
}
function renderHealthAlerts(){
 const alerts=state.devices.flatMap(device=>deviceAlerts(device,Number(state.server_time)).map(alert=>({...alert,device}))).sort((a,b)=>a.severity-b.severity);
 $('#device-alert-count').textContent=alerts.length;
 $('#device-alerts').innerHTML=alerts.slice(0,12).map(alert=>`<article class="device-alert severity-${alert.severity}"><div><strong>${esc(alert.title)}</strong><p>${esc(alert.device.name)} · ${esc(alert.device.reference)}</p><p>${esc(alert.detail)}</p><small>Last contact: ${esc(date(alert.device.last_seen))}</small></div>${account.role==='owner'?`<button class="secondary" data-device="${esc(alert.device.id)}">Check device</button>`:''}</article>`).join('')||emptyState('No attention items','Exceptions from the latest phone reports will appear here.');
 $('#device-alert-more').hidden=alerts.length<=12;
}
async function refresh(){const button=$('#refresh');button.disabled=true;$('#workspace').setAttribute('aria-busy','true');$('#loading-strip').hidden=false;try{state=await api('/admin/overview');try{const orders=await api('/admin/orders');state.transactions=orders.transactions;}catch{state.transactions_unavailable=true;}render();$('#sync-status').textContent='Updated '+new Date().toLocaleTimeString('en-ZA',{hour:'2-digit',minute:'2-digit'});$('#sync-dot').dataset.state='fresh';}catch(e){$('#sync-status').textContent='Refresh unavailable';$('#sync-dot').dataset.state='stale';throw e;}finally{button.disabled=false;$('#workspace').setAttribute('aria-busy','false');$('#loading-strip').hidden=true;}}
async function enter(){account=await api('/auth/me');if(typeof checkOnline!=='undefined')checkOnline.hidden=account.role!=='owner';$('#account').textContent=account.email;$('#new-customer').hidden=account.role!=='owner';$('#fleet-policy').hidden=true;$('#banking-settings').hidden=account.role!=='owner';$('#compose-message').hidden=account.role==='viewer';$('#login').hidden=true;$('#workspace').hidden=false;try{showView(localStorage.getItem('loop-admin-view')||'overview');}catch{}try{await refresh();}catch(e){error(e);}}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;const b=f.querySelector('button');b.disabled=true;$('#login-error').textContent='';try{await api('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(f)))});f.reset();await enter();}catch(err){$('#login-error').textContent=err.message;}finally{b.disabled=false;}});
$('#logout').onclick=async()=>{try{await api('/auth/logout',{method:'POST'});showLogin();}catch(e){error(e);}};
$('#refresh').onclick=()=>refresh().catch(error);$('#overview-search').oninput=renderOverviewRegister;$('#search').oninput=renderDevices;$('#customer-filter').onchange=renderDevices;
$('#menu-toggle').onclick=()=>{const open=$('.sidebar').classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');};
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('.sidebar').classList.contains('menu-open')){$('.sidebar').classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Open navigation');$('#menu-toggle').focus();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)showView(b.dataset.view);if(b.hasAttribute('data-refresh'))refresh().catch(error);if(b.hasAttribute('data-reset-device-filters')){$('#search').value='';$('#customer-filter').value='all';renderDevices();}if(b.hasAttribute('data-compose'))composeMessage();if(b.hasAttribute('data-enroll'))$('#new-customer').click();if(b.hasAttribute('data-clear-filters')){$('#search').value='';$('#customer-filter').value='all';renderDevices();$('#search').focus();}if(b.dataset.deviceFilter){$('#customer-filter').value=b.dataset.deviceFilter;showView('devices');renderDevices();}if(b.dataset.paymentFilter){paymentFilter=b.dataset.paymentFilter;renderPayments();}if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.dataset.qr){reissueEnrollment(b.dataset.qr).catch(error);}if(b.dataset.resolve){api('/admin/support/'+b.dataset.resolve+'/resolve',{method:'POST'}).then(()=>refresh()).catch(error);}if(b.dataset.reply){composeMessage(b.dataset.reply);}if(b.dataset.review){selectedClaim=state.claims.find(p=>p.id===b.dataset.review);$('#review-title').textContent=selectedClaim.name;$('#review-description').textContent=`${money(selectedClaim.amount)} EFT · ${selectedClaim.reference}. Confirm the settled transaction in your bank before approving.`;$('#review-form').reset();$('#review-dialog').showModal();}if(b.dataset.control)controlDevice(b.dataset.control).catch(error);if(b.dataset.device)openDevice(b.dataset.device);});
function openDevice(deviceId){unlockRequest++;issuedUnlock=null;$('#unlock-code-expiry').textContent='';$('#share-unlock-whatsapp').removeAttribute('href');$('#unlock-code-result').hidden=true;$('#unlock-code-value').textContent='';$('#generate-unlock-code').disabled=false;document.querySelector('.gateway-customer').hidden=false;selectedDevice=state.devices.find(d=>d.id===deviceId);$('#generate-temporary-code').disabled=!!selectedDevice.released||selectedDevice.enforcement_status==='not_enrolled';$('#ikpay-link-url').hidden=true;$('#copy-ikpay-link').hidden=true;$('#ikpay-link-status').textContent='';$('#create-ikpay-link').disabled=!!selectedDevice.released||selectedDevice.enforcement_status==='not_enrolled';$('#renew-ikpay-link').disabled=$('#create-ikpay-link').disabled;$('#fleet-explanation').hidden=true;$('#advanced-policy').open=false;$('#device-quick-controls').hidden=false;$('#control-status').textContent='';document.querySelectorAll('[data-control]').forEach(button=>button.disabled=!!selectedDevice.released||selectedDevice.enforcement_status==='not_enrolled');$('#fleet-confirmation').hidden=true;$('#view-identifiers').hidden=false;$('#policy-form').elements.confirm_all.required=false;$('#device-identifiers').textContent='';$('#device-title').textContent=selectedDevice.name;const plan=selectedDevice.payment_summary;$('#create-ikpay-link').textContent=plan?'Create '+money(plan.next_payment)+' payment link':'Create payment link';$('#device-summary').textContent=(plan?'Plan '+money(plan.contract_total)+' · Paid '+money(plan.approved_total)+' · Balance '+money(plan.remaining_balance)+' · '+plan.progress_percent+'% repaid · ':'')+`${selectedDevice.model||'Not enrolled'} · ${selectedDevice.enforcement_status.replaceAll('_',' ')} · ${Number(selectedDevice.acknowledged_revision)<Number(selectedDevice.revision)?'Device confirmation pending':'Current revision acknowledged'}`;let policy={};try{policy=typeof selectedDevice.policy==='string'?JSON.parse(selectedDevice.policy):selectedDevice.policy||{};}catch{}const f=$('#policy-form');for(const [k,v]of Object.entries(policy)){const field=f.elements.namedItem(k);if(!field)continue;if(field.type==='checkbox')field.checked=v;else field.value=field.type==='time'?String(Math.floor(v/60)).padStart(2,'0')+':'+String(v%60).padStart(2,'0'):Array.isArray(v)?v.join('\n'):v;}$('#policy-form').hidden=true;$('#release-form').hidden=!!selectedDevice.released;$('#release-form').reset();$('#device-dialog').showModal();}

function policyFrom(form){const f=form.elements;return{enforcement_enabled:f.enforcement_enabled.checked,block_factory_reset:f.block_factory_reset.checked,block_uninstall:f.block_uninstall.checked,block_wifi_changes:f.block_wifi_changes.checked,banking_packages:f.banking_packages.value.split(/[\n,]+/).map(s=>s.trim()).filter(Boolean),grace_hours:Number(f.grace_hours.value),update_window_start:timeMinutes(f.update_window_start.value),update_window_end:timeMinutes(f.update_window_end.value)};}
$('#new-customer').onclick=()=>{setEnrollmentStep(1);$('#enrollment-form').reset();$('#qr-form').reset();$('#usb-setup-status').textContent='';$('#enrollment-form').hidden=false;$('#enrollment-result').hidden=true;$('#qr-image').hidden=true;$('#qr-status').textContent='';$('#enrollment-dialog').showModal();};
$('#enrollment-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;busy(form,async()=>{const f=form.elements;enrollment=await api('/admin/enrollments',{method:'POST',body:JSON.stringify({name:f.name.value,phone:f.phone.value})});$('#result-server').value=enrollment.server_url;$('#result-token').value=enrollment.enrollment_token;$('#result-key').value=enrollment.public_key;$('#result-reference').textContent='EFT reference: '+enrollment.reference;form.hidden=true;$('#enrollment-result').hidden=false;setEnrollmentStep(2);const apk=await api('/admin/provisioning/apk');if(apk.available){$('#qr-form').elements.apk_url.value=apk.apk_url;$('#qr-form').elements.apk_sha256.value=apk.apk_sha256;if(apk.apk_url.startsWith('https://'))$('#qr-form').requestSubmit();}await refresh();});};
$('#qr-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;busy(f,async()=>{$('#qr-status').textContent='Preparing your enrollment QR…';const r=await fetch('/api/admin/provisioning/qr',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...Object.fromEntries(new FormData(f)),enrollment_token:enrollment.enrollment_token,format:'png'})});if(!r.ok){const b=await r.json();throw Error(typeof b.detail==='string'?b.detail:'Check the APK URL and checksum.');}if(qrUrl)URL.revokeObjectURL(qrUrl);qrUrl=URL.createObjectURL(await r.blob());$('#qr-image').onload=()=>{$('#qr-status').textContent='Ready to scan on the new or factory-reset phone.';};$('#qr-image').src=qrUrl;$('#qr-image').hidden=false;});};
$('#review-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;busy(f,async()=>{const result=await api('/admin/claims/'+selectedClaim.id+'/review',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(f)))});$('#review-dialog').close();notice(result.state==='approved'?'Payment approved. Unlock delivery awaits the handset’s next successful sync.':'Claim rejected. The paid deadline has not changed.');await refresh();});};
$('#policy-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;busy(f,async()=>{if(selectedDevice){await api('/admin/devices/'+selectedDevice.id+'/policy',{method:'PUT',body:JSON.stringify(policyFrom(f))});notice('Policy saved. Device confirmation is pending.');}else{const result=await api('/admin/fleet/policy',{method:'POST',body:JSON.stringify({request_key:requestKey(f),policy:policyFrom(f),apply_to_all_active:f.elements.confirm_all.checked})});notice('Policy saved for '+result.affected+' active devices. Individual confirmations are pending.');delete f.dataset.requestKey;}$('#device-dialog').close();await refresh();});};
$('#release-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;busy(f,async()=>{await api('/admin/devices/'+selectedDevice.id+'/release',{method:'POST',body:JSON.stringify({reason:f.elements.reason.value,full_payoff_confirmed:f.elements.full_payoff_confirmed.checked})});$('#device-dialog').close();notice('Permanent release recorded. Waiting for device confirmation.');await refresh();});};
enter().catch(e=>{if(e.status===401)showLogin();else{$('#login-error').textContent=e.message;error(e);}});
setInterval(()=>{if(account&&!document.querySelector('dialog[open]'))refresh().catch(error);},30000);

$('#view-identifiers').onclick=async()=>{try{const d=await api('/admin/devices/'+selectedDevice.id+'/identifiers');$('#device-identifiers').textContent=d.status==='available'?'IMEI: '+d.imeis.join(', ')+' · SIM carrier: '+d.sim_operator+' · '+d.sim_country:'Identifiers: '+d.status.replaceAll('_',' ');}catch(e){error(e);}};

function timeMinutes(value){const [hours,minutes]=value.split(":").map(Number);return hours*60+minutes;}

function requestKey(form){if(!form.dataset.requestKey)form.dataset.requestKey=crypto.randomUUID();return form.dataset.requestKey;}
function composeMessage(deviceId=''){
  const form=$('#message-form');form.reset();delete form.dataset.requestKey;
  $('#message-recipient').innerHTML='<option value="all">Every active enrolled customer</option>'+state.devices.filter(d=>!d.released&&d.enforcement_status!=='not_enrolled').map(d=>`<option value="${esc(d.id)}">${esc(d.name)} · ${esc(d.reference)}</option>`).join('');
  if(deviceId)form.elements.recipient.value=deviceId;
  $('#message-dialog').showModal();
}
$('#compose-message').onclick=()=>composeMessage();
$('#message-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;busy(form,async()=>{
  const recipient=form.elements.recipient.value;
  const sent=await api('/admin/messages',{method:'POST',body:JSON.stringify({request_key:requestKey(form),title:form.elements.title.value,message:form.elements.message.value,all_active:recipient==='all',device_ids:recipient==='all'?[]:[recipient]})});
  delete form.dataset.requestKey;$('#message-dialog').close();notice('Message queued for '+sent.recipients+' phones. Delivery receipts appear as devices connect.');await refresh();
});};
$('#fleet-policy').onclick=()=>{
  selectedDevice=null;document.querySelector('.gateway-customer').hidden=true;const f=$('#policy-form');f.reset();delete f.dataset.requestKey;
  $('#device-title').textContent='Policy for every active phone';const plan=selectedDevice.payment_summary;$('#create-ikpay-link').textContent=plan?'Create '+money(plan.next_payment)+' payment link':'Create payment link';$('#device-summary').textContent=(plan?'Plan '+money(plan.contract_total)+' · Paid '+money(plan.approved_total)+' · Balance '+money(plan.remaining_balance)+' · '+plan.progress_percent+'% repaid · ':'')+'Each phone reports back after applying the change.';
  $('#fleet-explanation').hidden=false;$('#advanced-policy').open=true;$('#device-quick-controls').hidden=true;$('#fleet-confirmation').hidden=false;f.elements.confirm_all.required=true;
  $('#view-identifiers').hidden=true;$('#device-identifiers').textContent='';$('#release-form').hidden=true;f.hidden=false;
  f.elements.grace_hours.value=24;f.elements.update_window_start.value='02:00';f.elements.update_window_end.value='04:00';
  $('#device-dialog').showModal();
};

$('#banking-settings').onclick=async()=>{try{const bank=await api('/admin/banking');const form=$('#banking-form');form.reset();for(const key of ['bank','account_holder','account_number','branch_code'])form.elements.namedItem(key).value=bank[key]||'';$('#banking-dialog').showModal();}catch(e){error(e);}};
$('#banking-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;busy(f,async()=>{const body=Object.fromEntries(new FormData(f));body.details_verified=f.elements.details_verified.checked;await api('/admin/banking',{method:'PUT',body:JSON.stringify(body)});$('#banking-dialog').close();notice('Verified EFT details saved. Connected phones will receive the update.');await refresh();});};

async function reissueEnrollment(deviceId){
 enrollment=await api('/admin/devices/'+deviceId+'/enrollment',{method:'POST'});
 setEnrollmentStep(2);$('#qr-form').reset();$('#usb-setup-status').textContent='';$('#enrollment-form').hidden=true;$('#enrollment-result').hidden=false;$('#qr-image').hidden=true;$('#qr-status').textContent='';
 $('#result-server').value=enrollment.server_url;$('#result-token').value=enrollment.enrollment_token;$('#result-key').value=enrollment.public_key;$('#result-reference').textContent='EFT reference: '+enrollment.reference;
 $('#enrollment-dialog').showModal();
 const apk=await api('/admin/provisioning/apk');if(apk.available){$('#qr-form').elements.apk_url.value=apk.apk_url;$('#qr-form').elements.apk_sha256.value=apk.apk_sha256;$('#qr-form').requestSubmit();}
 await refresh();
}

async function controlDevice(action){
 if(!selectedDevice||!['lock','unlock','grace'].includes(action))return;
 const buttons=[...document.querySelectorAll('[data-control]')];buttons.forEach(button=>button.disabled=true);
 const deviceId=selectedDevice.id;
 if(!controlRequest||controlRequest.deviceId!==deviceId||controlRequest.action!==action)controlRequest={deviceId,action,key:crypto.randomUUID()};
 try{
  await api('/admin/devices/'+deviceId+'/control',{method:'POST',body:JSON.stringify({action,request_key:controlRequest.key})});
  controlRequest=null;
  $('#control-status').textContent=({lock:'Lock requested. Waiting for the phone to confirm.',unlock:'Unlock requested. Paid time and grace rules still apply.',grace:'24-hour grace granted. Waiting for the phone to confirm.'})[action];
  await refresh();selectedDevice=state.devices.find(device=>device.id===deviceId)||selectedDevice;
 }finally{buttons.forEach(button=>button.disabled=!!selectedDevice.released||selectedDevice.enforcement_status==='not_enrolled');}
}

async function connectNativeAdmin(){
 const ticket=new URLSearchParams(location.search).get('connect_admin');
 const [download,pending]=await Promise.all([api('/admin/mobile/installer'),api('/admin/mobile/pending')]);
 if(download.available&&download.apk_url){$('#admin-app-download').href=download.apk_url;$('#admin-app-download').hidden=false;}
 const requests=pending.requests||[];
 $('#pending-admin-requests').innerHTML=requests.map(request=>'<article class="pair-request"><div><strong>'+esc(request.name)+'</strong><p>Match this code in your app: <b>'+esc(request.code)+'</b></p></div><button data-approve-pair="'+esc(request.ticket)+'">Approve this app</button></article>').join('')||'<p>No app is waiting yet. In Loop Secure Admin on your phone, tap Sign in.</p>';
 document.querySelectorAll('[data-approve-pair]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api('/admin/mobile/approve',{method:'POST',body:JSON.stringify({ticket:button.dataset.approvePair})});button.textContent='Connected';$('#admin-connect-status').textContent='Connected. Return to Loop Secure Admin; your records will load automatically.';history.replaceState(null,'',location.pathname);}catch(e){button.disabled=false;error(e);}});
 $('#approve-admin-connect').hidden=true;
 if(requests.length)$('#admin-connection').open=true;
 if(ticket){$('#admin-connection').open=true;$('#admin-connect-status').textContent='Your app is waiting. Match the code below with your phone, then tap Approve this app.';$('#admin-connection').scrollIntoView({block:'center'});}
}

$('#connect-admin-app').onclick=()=>{$('#admin-connection').open=true;document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('#admin-connection').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});connectNativeAdmin().catch(error);};

const nativeCheck=setInterval(()=>{if(account){clearInterval(nativeCheck);connectNativeAdmin().catch(error);}},500);

function renderFleetHealth(){const devices=state.devices.filter(d=>d.enforcement_status!=='not_enrolled'&&!d.released);const recent=devices.filter(d=>d.last_seen&&state.server_time-d.last_seen<=900).length;const ratio=devices.length?Math.round(recent/devices.length*100):0;$('#fleet-health-percent').textContent=devices.length?ratio+'%':'—';$('#fleet-health-meter').value=ratio;$('#fleet-health-legend').innerHTML='<p><b>'+recent+'</b> recent contact</p><p><b>'+(devices.length-recent)+'</b> no recent report</p><p><b>'+devices.length+'</b> managed devices</p>';$('#recent-activity').innerHTML=state.audit.slice(0,3).map(a=>'<div class="recent-event"><span class="event-dot"></span><div><strong>'+esc(a.action.replaceAll('_',' '))+'</strong><small>'+esc(date(a.at))+'</small></div></div>').join('')||'<div class="empty"><strong>Nothing recorded yet.</strong><p>Recent workspace actions appear here.</p></div>';}
$('#revoke-admin-apps').onclick=async()=>{if(!confirm('Disconnect every Android admin app? Website access stays available.'))return;try{await api('/admin/mobile/revoke-all',{method:'POST'});notice('Android admin sessions revoked.');}catch(e){error(e);}};

$('#download-usb-enrollment').onclick=async()=>{if(!enrollment)return;const button=$('#download-usb-enrollment');button.disabled=true;$('#usb-setup-status').textContent='Preparing the signed client and one-time enrollment code…';try{const response=await fetch('/api/admin/provisioning/usb-bundle',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enrollment_token:enrollment.enrollment_token})});if(!response.ok){const failure=await response.json();throw new Error(failure.detail||'USB bundle could not be prepared.');}const url=URL.createObjectURL(await response.blob());const link=document.createElement('a');link.href=url;link.download='Loop-Secure-Windows-Enrollment-'+enrollment.reference+'.zip';link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);$('#usb-setup-status').textContent='Extract the customer ZIP into its own folder and run START-HERE.cmd. If asked the first time, choose adb.exe. Approve the phone’s USB debugging prompt, then finish setup on the phone.';}catch(e){error(e);$('#usb-setup-status').textContent='Download failed. Refresh the enrollment if its code has expired.';}finally{button.disabled=false;}};
$('#qr-image').onclick=()=>{let dialog=$('#qr-enlarged');if(!dialog){dialog=document.createElement('dialog');dialog.id='qr-enlarged';dialog.innerHTML='<p>Scan this from Android’s initial device setup. Keep the full white border visible.</p><img alt="Enlarged Android enrollment QR"><button type="button">Close</button>';dialog.querySelector('button').onclick=()=>dialog.close();document.body.append(dialog);}dialog.querySelector('img').src=$('#qr-image').src;dialog.showModal();};

