document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'&&account&&!document.querySelector('dialog[open]')){event.preventDefault();showView('devices');$('#search').focus();}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-copy-reference]');if(!button)return;try{await navigator.clipboard.writeText(button.dataset.copyReference);notice('Customer reference copied.');}catch{notice('Copy unavailable. Select the customer reference and copy it manually.');}});
const connectionBanner=document.createElement('p');connectionBanner.className='connection-banner';connectionBanner.setAttribute('role','status');connectionBanner.hidden=true;$('#workspace').prepend(connectionBanner);
function reportConnection(){connectionBanner.hidden=navigator.onLine;connectionBanner.textContent=navigator.onLine?'':'You are offline. Displayed records may be out of date; changes need an internet connection.';if(!navigator.onLine){$('#sync-status').textContent='Offline · saved screen';$('#sync-dot').dataset.state='stale';}}
window.addEventListener('offline',reportConnection);window.addEventListener('online',()=>{reportConnection();if(account)refresh().catch(error);});reportConnection();
function csvCell(value){let text=String(value??'');if(/^\s*[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';}
function customerCsv(devices){const rows=[['Customer','Reference','Phone','Reported status','Approved ZAR','Approved payments'],...devices.map(d=>[d.name,d.reference,d.phone,d.enforcement_status,d.approved_total??'',d.approved_count??''])];return '\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n')+'\r\n';}
const exportCustomers=document.createElement('button');exportCustomers.type='button';exportCustomers.className='secondary';exportCustomers.textContent='Download customer list';exportCustomers.setAttribute('aria-label','Download the current customer register as CSV');$('#customer-filter').closest('.view-toolbar').append(exportCustomers);
exportCustomers.onclick=()=>{if(!account)return;const url=URL.createObjectURL(new Blob([customerCsv(state.devices)],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='Loop-Secure-Customers-'+new Date().toISOString().slice(0,10)+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);notice('Customer list downloaded. Keep the file private.');};

