function compareCustomerRecords(a,b,order){if(order==='due')return (a.due??Number.MAX_SAFE_INTEGER)-(b.due??Number.MAX_SAFE_INTEGER)||String(a.name||'').localeCompare(String(b.name||''));if(order==='seen')return (b.last_seen||0)-(a.last_seen||0)||String(a.name||'').localeCompare(String(b.name||''));return String(a.name||'').localeCompare(String(b.name||''),undefined,{sensitivity:'base'});}
function matchesPaymentQuery(claim,query){const q=String(query).trim().toLowerCase();return !q||[claim.name,claim.reference,claim.bank_reference,claim.receipt_reference].some(v=>String(v||'').toLowerCase().includes(q));}
const loadingStrip=document.createElement('div');loadingStrip.id='loading-strip';loadingStrip.hidden=true;loadingStrip.setAttribute('role','status');loadingStrip.textContent='Refreshing customer records…';$('#workspace').prepend(loadingStrip);
const sortLabel=document.createElement('label');sortLabel.className='filter-label';sortLabel.append(document.createTextNode('Sort '));const customerSort=document.createElement('select');customerSort.id='customer-sort';for(const [value,label]of [['name','Customer name'],['due','Next paid deadline'],['seen','Most recent contact']]){const option=document.createElement('option');option.value=value;option.textContent=label;customerSort.append(option);}sortLabel.append(customerSort);$('#customer-filter').closest('.view-toolbar').append(sortLabel);customerSort.onchange=renderDevices;
const chips=document.createElement('div');chips.className='customer-chips';chips.setAttribute('role','group');chips.setAttribute('aria-label','Quick customer filters');for(const [value,label]of [['all','All'],['connected','Recent contact'],['overdue','Past paid date'],['setup','Setup pending']]){const b=document.createElement('button');b.type='button';b.className='secondary';b.dataset.quickFilter=value;b.dataset.label=label;b.onclick=()=>{$('#customer-filter').value=value;renderDevices();};chips.append(b);}$('#devices-view .view-toolbar').after(chips);
function refreshCustomerChips(){document.querySelectorAll('[data-quick-filter]').forEach(b=>{const f=b.dataset.quickFilter;const count=state.devices.filter(d=>f==='all'||f==='setup'&&d.enforcement_status==='not_enrolled'||f==='overdue'&&!d.released&&d.due<state.server_time||f==='connected'&&!d.released&&d.enforcement_status!=='not_enrolled'&&d.last_seen&&state.server_time-d.last_seen<=900).length;b.textContent=b.dataset.label+' · '+count;b.setAttribute('aria-pressed',String($('#customer-filter').value===f));});}
const paymentSearchLabel=document.createElement('label');paymentSearchLabel.className='search-field payment-search';const paymentSearch=document.createElement('input');paymentSearch.id='payment-search';paymentSearch.type='search';paymentSearch.placeholder='Find customer or bank reference';paymentSearch.setAttribute('aria-label','Search payment records');paymentSearchLabel.append(paymentSearch);$('#payments-view .view-toolbar').append(paymentSearchLabel);paymentSearch.oninput=renderPayments;
const density=document.createElement('button');density.type='button';density.className='secondary density-toggle';density.textContent='Compact rows';density.setAttribute('aria-pressed','false');$('.header-actions').prepend(density);
function applyDensity(compact){document.documentElement.dataset.density=compact?'compact':'comfortable';density.setAttribute('aria-pressed',String(compact));density.textContent=compact?'Comfortable rows':'Compact rows';try{localStorage.setItem('loop-density',compact?'compact':'comfortable');}catch{}}
