const help=document.createElement('dialog');help.id='workspace-help';help.setAttribute('aria-labelledby','workspace-help-title');const helpTitle=document.createElement('h2');helpTitle.id='workspace-help-title';helpTitle.textContent='A little help, when you need it';help.append(helpTitle);const helpList=document.createElement('ol');for(const text of ['Press Ctrl+K or Command+K to find a customer. Escape closes a dialog.','New phone: open the customer’s Setup QR, choose Windows USB, extract the full ZIP and run START-HERE.cmd. Codes last 30 minutes.','Existing phone: use the update ZIP to preserve its account and device owner.','Ownership check failed: read Ownership-check.txt. Keep the phone unlocked; a new download does not fix every Android error.','Review an EFT against settled bank funds before approving. A claim is not proof of payment.']){const item=document.createElement('li');item.textContent=text;helpList.append(item);}help.append(helpList);const helpClose=document.createElement('button');helpClose.type='button';helpClose.textContent='Got it';helpClose.onclick=()=>help.close();help.append(helpClose);document.body.append(help);const helpButton=document.createElement('button');helpButton.type='button';helpButton.className='secondary';helpButton.textContent='Setup help';helpButton.onclick=()=>help.showModal();$('.header-actions').append(helpButton);

$('#open-ikpay-settings').onclick=async()=>{try{const status=await api('/admin/payments/ikhokha');const form=$('#ikpay-settings-form');form.reset();form.elements.enabled.checked=status.enabled;$('#ikpay-provider-status').textContent=status.configured?'Saved merchant application '+status.app_id_hint+(status.enabled?' · online payments enabled':' · disabled'):'No merchant application configured yet.';$('#ikpay-connection-addresses').textContent='Callback: '+status.callback_url+' · Return: '+status.return_url;$('#ikpay-settings-dialog').showModal();}catch(e){error(e);}};
$('#ikpay-settings-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;busy(form,async()=>{const result=await api('/admin/payments/ikhokha',{method:'PUT',body:JSON.stringify({app_id:form.elements.app_id.value,app_secret:form.elements.app_secret.value,enabled:form.elements.enabled.checked})});form.elements.app_secret.value='';$('#ikpay-settings-dialog').close();notice(result.enabled?'iKhokha connection saved. Complete a real payment test before relying on automatic approval.':'Online payment connection disabled.');});};
$('#renew-ikpay-link').onclick=async()=>{if(!selectedDevice||!confirm('Replace a failed checkout? If the customer was debited, check payment status first. The server must confirm the old link is unpaid before creating a replacement.'))return;const id=selectedDevice.id,button=$('#renew-ikpay-link');button.disabled=true;try{const result=await api('/admin/devices/'+id+'/payment-link',{method:'POST',body:JSON.stringify({fresh:true})});if(selectedDevice?.id!==id)return;if(result.state==='paid'||result.state==='review_required'){$('#ikpay-link-url').hidden=true;$('#copy-ikpay-link').hidden=true;$('#ikpay-link-status').textContent=result.state==='paid'?'Payment already verified; no new checkout was created.':'Payment requires administrator attention; no new checkout was created.';return;}$('#ikpay-link-url').value=result.checkout_url;$('#ikpay-link-url').hidden=false;$('#copy-ikpay-link').hidden=false;$('#ikpay-link-status').textContent='Fresh checkout ready. The customer must close the failed page and reopen Pay online, or use this new link.';}catch(e){$('#ikpay-link-status').textContent=e.message;}finally{button.disabled=false;}};
$('#create-ikpay-link').onclick=async()=>{if(!selectedDevice)return;const id=selectedDevice.id,button=$('#create-ikpay-link');button.disabled=true;$('#ikpay-link-status').textContent='Preparing the customer checkout…';try{const result=await api('/admin/devices/'+id+'/payment-link',{method:'POST',body:'{}'});if(selectedDevice?.id!==id)return;if(result.state==='paid'||result.state==='review_required'){$('#ikpay-link-url').hidden=true;$('#copy-ikpay-link').hidden=true;$('#ikpay-link-status').textContent=result.state==='paid'?'Payment already verified; no new checkout was created.':'Payment requires administrator attention; no new checkout was created.';return;}$('#ikpay-link-url').value=result.checkout_url;$('#ikpay-link-url').hidden=false;$('#copy-ikpay-link').hidden=false;$('#ikpay-link-status').textContent='R300 checkout ready. Share this link with the intended customer. Opening a link is not confirmation of payment.';}catch(e){$('#ikpay-link-status').textContent=e.message;}finally{button.disabled=false;}};
$('#copy-ikpay-link').onclick=async()=>{try{await navigator.clipboard.writeText($('#ikpay-link-url').value);notice('Customer payment link copied.');}catch(e){$('#ikpay-link-url').focus();$('#ikpay-link-url').select();notice('Select and copy the payment link above.');}};

// Signed-app version reports are telemetry, never proof of payment or installation success.
function updateNeeded(d){return !d.released&&Number.isSafeInteger(d.app_version?.code)&&Number.isSafeInteger(state.client_release?.version_code)&&d.app_version.code<state.client_release.version_code;}
function updateDescription(d){const v=d.app_version;if(!v)return 'App version not reported';const stages={checking:'Checking',current:'Last check: current',downloading:'Downloading',ready:'Ready to install',installing:'Installation requested',failed:'Update needs retry',idle:'Awaiting update check'};return 'App '+v.name+' · '+(stages[v.update_state]||'Reported')+(v.update_state==='downloading'?' '+v.progress+'%':'')+' · '+(updateNeeded(d)?'New version available · ':'')+'reported '+date(v.reported_at);}
function renderUpdateFleet(){const panel=$('#update-fleet');if(!panel)return;const known=state.devices.filter(d=>d.app_version),behind=state.devices.filter(updateNeeded),ready=state.devices.filter(d=>d.app_version?.update_state==='ready'),failed=state.devices.filter(d=>d.app_version?.update_state==='failed');$('#update-fleet-summary').textContent='Latest customer release '+(state.client_release?.version||'not reported')+' · '+known.length+' version reports · '+behind.length+' behind latest · '+ready.length+' ready to install · '+failed.length+' need retry. Versions are last device reports; offline phones may be stale.';}
const updatePanel=document.createElement('section');updatePanel.id='update-fleet';updatePanel.className='panel gateway-setup';updatePanel.innerHTML='<div><h2>Customer app updates</h2><p id="update-fleet-summary" aria-live="polite"></p></div><button type="button" class="secondary" id="show-update-needed">Show older apps</button>';$('#devices-view').prepend(updatePanel);$('#show-update-needed').onclick=()=>{$('#customer-filter').value='update';renderDevices();};const updateFilter=document.createElement('option');updateFilter.value='update';updateFilter.textContent='Update available';$('#customer-filter').append(updateFilter);
const checkOnline=document.createElement('button');checkOnline.type='button';checkOnline.className='secondary';checkOnline.textContent='Verify recent online payments';$('#payments-view .gateway-setup').append(checkOnline);checkOnline.onclick=async()=>{if(account?.role!=='owner')return;checkOnline.disabled=true;try{await api('/admin/payments/ikhokha/reconcile',{method:'POST',body:'{}'});await refresh();notice('Recent online payments checked against iKhokha. Unconfirmed payments remain pending.');}catch(e){error(e);}finally{checkOnline.disabled=false;}};
function paymentCsv(claims){return '\uFEFF'+[['Customer reference','Claim ID','Claim status','Claimed ZAR','Bank reference','Created','Reviewed'],...claims.map(c=>[c.customer_reference||c.reference||'',c.id,c.state,c.amount,c.bank_reference||c.reference||'',date(c.submitted),c.reviewed?date(c.reviewed):''])].map(row=>row.map(csvCell).join(',')).join('\r\n')+'\r\n';}
const exportPayments=document.createElement('button');exportPayments.type='button';exportPayments.className='secondary';exportPayments.textContent='Export displayed claims';$('#payments-view .view-toolbar').append(exportPayments);exportPayments.onclick=()=>{if(!account)return;const claims=state.claims.filter(c=>(paymentFilter==='all'||c.state===paymentFilter)&&matchesPaymentQuery(c,$('#payment-search')?.value||'')),url=URL.createObjectURL(new Blob([paymentCsv(claims)],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='Loop-Secure-Claims-'+new Date().toISOString().slice(0,10)+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);notice('Displayed claim records exported. Claims are not proof that funds were received. Keep the file private.');};

// Recovery codes never enter localStorage, exports or the activity log.
let issuedUnlock=null,unlockRequest=0;
async function generateUnlockCode(temporary=false){
 if(!selectedDevice||account?.role!=='owner')return;
 const device=selectedDevice,id=device.id,request=++unlockRequest;const paidButton=$('#generate-unlock-code'),temporaryButton=$('#generate-temporary-code');paidButton.disabled=true;temporaryButton.disabled=true;$('#unlock-code-result').hidden=true;$('#share-unlock-whatsapp').removeAttribute('href');issuedUnlock=null;
 try{
  const result=await api('/admin/devices/'+id+(temporary?'/temporary-unlock-code':'/unlock-code'),{method:'POST',body:'{}'});if(request!==unlockRequest||selectedDevice?.id!==id)return;
  const code=String(result.code);if(!/^[0-9]{10}$/.test(code)||(temporary&&result.duration_seconds!==300))throw Error('The server did not return a valid code.');
  issuedUnlock={id,code,expires:result.expires,temporary};$('#unlock-code-value').textContent=code.slice(0,5)+' '+code.slice(5);$('#unlock-code-value').setAttribute('aria-label',temporary?'One-time five-minute access code':'One-time unlock code');
  const details=temporary?'Five minutes starts when the code is verified online. The timer then runs on the phone, even offline; normal finance restrictions resume afterward. No payment or paid deadline is added.':'One use, for this phone. Only restores recorded paid access. No payment or paid time is added.';
  $('#unlock-code-expiry').textContent='Code expires '+date(result.expires)+'. '+details;
  let phone=String(device.phone||'').replace(/[^0-9]/g,'');if(phone.startsWith('0')&&phone.length===10)phone='27'+phone.slice(1);const share=$('#share-unlock-whatsapp');share.hidden=!/^[1-9][0-9]{7,14}$/.test(phone);
  const entry=temporary?'Five-minute access code':'Enter unlock code';share.href='https://wa.me/'+phone+'?text='+encodeURIComponent('Loop Secure '+(temporary?'five-minute access code':'unlock code')+': '+code+'. For your phone only. Code expires '+date(result.expires)+'. Enter it in Loop Secure → Support → '+entry+'. Internet required to verify the code. '+details);$('#unlock-code-result').hidden=false;
 }catch(e){if(request===unlockRequest)error(e);}finally{if(request===unlockRequest){paidButton.disabled=false;temporaryButton.disabled=!!selectedDevice?.released||selectedDevice?.enforcement_status==='not_enrolled';}}
}
$('#generate-unlock-code').onclick=()=>generateUnlockCode(false);
$('#generate-temporary-code').onclick=()=>generateUnlockCode(true);
$('#share-unlock-whatsapp').onclick=e=>{if(!issuedUnlock||selectedDevice?.id!==issuedUnlock.id||Date.now()/1000>=issuedUnlock.expires){e.preventDefault();notice('This code is no longer available. Generate a fresh code.');}};
$('#copy-unlock-code').onclick=async()=>{if(!issuedUnlock||selectedDevice?.id!==issuedUnlock.id)return;if(Date.now()/1000>=issuedUnlock.expires){notice('This code has expired. Generate a fresh code.');return;}try{await navigator.clipboard.writeText(issuedUnlock.code);notice('One-use unlock code copied. Share it only with this customer.');}catch{notice('Select the displayed code to copy it.');}};
$('#device-dialog').addEventListener('close',()=>{unlockRequest++;issuedUnlock=null;$('#unlock-code-expiry').textContent='';$('#unlock-code-value').textContent='';$('#unlock-code-result').hidden=true;$('#share-unlock-whatsapp').removeAttribute('href');});

const themeControl=document.createElement('label');themeControl.className='theme-control';themeControl.textContent='Appearance';const themeChoice=document.createElement('select');themeChoice.id='theme-choice';themeChoice.setAttribute('aria-label','Appearance');for(const [value,label]of [['system','Follow device'],['light','Light'],['dark','Dark']]){const option=document.createElement('option');option.value=value;option.textContent=label;themeChoice.append(option);}themeControl.append(themeChoice);document.querySelector('.workspace-toolbar').append(themeControl);const themeMedia=matchMedia('(prefers-color-scheme: dark)');let selectedTheme='system';try{const saved=localStorage.getItem('loop-appearance');if(['system','light','dark'].includes(saved))selectedTheme=saved;}catch{}themeChoice.value=selectedTheme;function applyAppearance(){document.documentElement.dataset.theme=selectedTheme==='system'?(themeMedia.matches?'dark':'light'):selectedTheme;}themeChoice.onchange=()=>{selectedTheme=themeChoice.value;try{localStorage.setItem('loop-appearance',selectedTheme);}catch{}applyAppearance();};themeMedia.addEventListener('change',applyAppearance);applyAppearance();

function renderTransactions(){let section=$('#online-transactions');if(!section){section=document.createElement('section');section.id='online-transactions';$('#payments-view').append(section);}const transactions=state.transactions||[];if(state.transactions_unavailable){section.innerHTML='<h2>Online payment attempts</h2><p>Order history could not be loaded. Refresh to retry. Payment verification continues separately.</p>';return;}section.innerHTML='<h2>Online payment attempts</h2><p>Latest 200 orders. A reported checkout failure is separate from provider-confirmed payment. Refresh or verify recent payments to reconcile.</p>'+transactions.map(p=>`<article class="activity"><div><strong>${esc(p.name)} · ${esc(p.amount_minor==null?"Amount unavailable":money(p.amount_minor/100))}</strong><p>${esc(p.reference)} · Order ${esc(p.order_id)}</p><p>${esc(p.state==='paid'?'Payment verified':p.state==='review_required'?'Needs review':p.state==='failed'?'Link creation failed':p.checkout_outcome==='failure'?'Checkout reported failed':p.checkout_outcome==='attempt_limit'?'Attempt limit reached':p.checkout_outcome==='cancel'?'Checkout cancelled':p.state==='creating'?'Creating checkout':p.checkout_outcome==='success'?'Checkout returned success; awaiting verification':'Awaiting payment confirmation')} · ${esc(date(p.created))}</p></div></article>`).join('')||'<p>No online orders recorded yet.</p>';}
